// AFFIFLOW_ASSISTED_MEDIA_PHASE2
readAssistedSession() {
  if (!fs.existsSync(this.assistedSessionPath)) {
    return null;
  }

  let session;

  try {
    session = JSON.parse(
      fs.readFileSync(this.assistedSessionPath, "utf8"),
    );
  } catch {
    throw new Error(
      "The active assisted media session is invalid.",
    );
  }

  const productId =
    normalizeString(
      session?.productId,
      "productId",
      150,
      true,
    );

  const candidate =
    this.statements
      .findAssistedCandidate
      .get(productId);

  if (!candidate) {
    throw new Error(
      "The imported Product Catalog record for this capture session was not found.",
    );
  }

  const mediaState =
    this.statements
      .getAssistedMediaState
      .get(
        candidate.candidateId,
      ) || null;

  return {
    sessionId:
      normalizeString(
        session?.sessionId,
        "sessionId",
        100,
      ),

    productId:
      candidate.productId,

    candidateId:
      candidate.candidateId,

    productName:
      candidate.name ||
      session.productName ||
      "Shopee Product",

    productUrl:
      session.productUrl ||
      candidate.affiliateLink ||
      candidate.sourceUrl,

    createdAt:
      session.createdAt || "",

    sessionStatus:
      session.status ||
      "Needs Capture",

    mediaState,
  };
}

getAssistedStatus(candidateId) {
  const normalizedCandidateId =
    normalizeString(
      candidateId,
      "candidateId",
      100,
      true,
    );

  const mediaState =
    this.statements
      .getAssistedMediaState
      .get(
        normalizedCandidateId,
      );

  if (!mediaState) {
    throw new Error(
      "Assisted media state was not found.",
    );
  }

  return mediaState;
}

completeAssistedSession(input) {
  const session =
    this.readAssistedSession();

  if (!session) {
    return {
      ok: true,
      updated: false,
    };
  }

  const candidateId =
    normalizeString(
      input?.candidateId,
      "candidateId",
      100,
      true,
    );

  if (
    candidateId !==
    session.candidateId
  ) {
    throw new Error(
      "The completed candidate does not match the active session.",
    );
  }

  const current =
    JSON.parse(
      fs.readFileSync(
        this.assistedSessionPath,
        "utf8",
      ),
    );

  current.status = "Ready";
  current.completedAt =
    new Date().toISOString();

  fs.writeFileSync(
    this.assistedSessionPath,
    JSON.stringify(
      current,
      null,
      2,
    ) + "\n",
    "utf8",
  );

  return {
    ok: true,
    updated: true,
  };
}

routes:
if (
  request.method === "GET" &&
  requestUrl.pathname ===
    "/api/assisted/session"
) {
  writeJson(
    response,
    200,
    {
      ok: true,
      session:
        this.readAssistedSession(),
    },
  );
  return;
}

if (
  request.method === "GET" &&
  requestUrl.pathname ===
    "/api/assisted/status"
) {
  writeJson(
    response,
    200,
    {
      ok: true,
      state:
        this.getAssistedStatus(
          requestUrl.searchParams
            .get("candidateId") ||
            "",
        ),
    },
  );
  return;
}

if (
  request.method === "POST" &&
  requestUrl.pathname ===
    "/api/assisted/complete"
) {
  const body =
    await readJsonBody(
      request,
    );

  writeJson(
    response,
    200,
    this.completeAssistedSession(
      body,
    ),
  );
  return;
}
